link.script:
import { initializeApp } from "https://www.gstatic.com/firebasejs/11.1.0/firebase-app.js";
import { getFirestore, collection, addDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/11.1.0/firebase-firestore.js";
import { getAuth, signInAnonymously } from "https://www.gstatic.com/firebasejs/11.1.0/firebase-auth.js";

const firebaseConfig = JSON.parse(__firebase_config);
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);
const auth = getAuth(app);
const appId = typeof __app_id !== 'undefined' ? __app_id : 'hassan-jatoi-poetry';

window.handleSubscribe = async (event) => {
    event.preventDefault();
    const emailInput = document.getElementById('sub-email');
    const statusMsg = document.getElementById('sub-status');
    const email = emailInput.value.trim();
    if(!email) return;
    try {
        statusMsg.textContent = "Processing...";
        await signInAnonymously(auth);
        await addDoc(collection(db, 'artifacts', appId, 'public', 'data', 'subscribers'), {
            email: email,
            timestamp: serverTimestamp(),
            source: window.location.hostname
        });
        statusMsg.innerHTML = "Successfully Subscribed!";
        emailInput.value = "";
        setTimeout(closeModal, 2000);
    } catch (error) {
        statusMsg.innerHTML = "Error. Please try again.";
    }
};

body.script:
        function openModal() { document.getElementById('sub-modal').style.display = 'flex'; }
